-- ====================================================================
-- YAAD Production - Master Catalog Items & Cloudinary Images Migration
-- File: supabase/migrations/20261023_catalog_item_images.sql
-- Description:
--   1. Creates public.items table if missing (with image_url & cloudinary_public_id).
--      Deliberately NO foreign keys to categories or subcategories because a live
--      probe on 2026-10-23 verified that subcategories does not exist on the live
--      database and categories returned no rows to the public anon key.
--      category_id is a plain TEXT id matching the app's CategoryId types.
--   2. Ensures image_url and cloudinary_public_id columns exist idempotently.
--   3. Sets up indexes on category_id and canonical_name.
--   4. Grants public read to anon, full CRUD to authenticated and service_role.
--   5. Enables RLS with permissive public read policy (anon can sync catalog).
--   6. Seeds the 89 master catalog items from INITIAL_MASTER_CATALOG with
--      ON CONFLICT (id) DO NOTHING so admin edits/images are never overwritten.
-- Idempotency: Fully safe to run multiple times without data loss.
-- ====================================================================

-- 1. ITEMS TABLE (Master Catalog)
CREATE TABLE IF NOT EXISTS public.items (
  id TEXT PRIMARY KEY,
  canonical_name TEXT NOT NULL,
  english_name TEXT NOT NULL,
  urdu_name TEXT NOT NULL,
  roman_urdu_names TEXT[] DEFAULT '{}',
  category_id TEXT NOT NULL,
  subcategory_id TEXT,
  common_misspellings TEXT[] DEFAULT '{}',
  searchable_terms TEXT[] DEFAULT '{}',
  default_unit TEXT DEFAULT 'kg',
  emoji TEXT,
  active BOOLEAN DEFAULT TRUE,
  created_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL,
  updated_at TIMESTAMPTZ DEFAULT timezone('utc'::text, now()) NOT NULL,
  image_url TEXT,
  cloudinary_public_id TEXT
);

-- 2. ENSURE IMAGE COLUMNS EXIST IDEMPOTENTLY
ALTER TABLE public.items ADD COLUMN IF NOT EXISTS image_url TEXT;
ALTER TABLE public.items ADD COLUMN IF NOT EXISTS cloudinary_public_id TEXT;

-- 3. INDEXES
CREATE INDEX IF NOT EXISTS idx_items_category_id ON public.items (category_id);
CREATE INDEX IF NOT EXISTS idx_items_canonical_name ON public.items (canonical_name);

-- 4. GRANTS (Standing post-Oct-30 rule for new tables)
GRANT SELECT ON public.items TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.items TO authenticated, service_role;

-- 5. ROW LEVEL SECURITY (Public read for client catalog sync, writes restricted to service role)
ALTER TABLE public.items ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Allow public read access on items" ON public.items;
CREATE POLICY "Allow public read access on items" ON public.items FOR SELECT USING (true);

-- 6. SEED INITIAL 89 MASTER CATALOG ITEMS (ON CONFLICT DO NOTHING)
